import sys
from datetime import date, timedelta, datetime

def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)


def clock(total):
    return f"{total // 60:02d}:{total % 60:02d}"


def main():
    settings = {}
    busy = {}
    for line in sys.stdin:
        parts = line.split()
        if not parts:
            continue
        if parts[0] == "busy":
            who, day_str, start_str, end_str = parts[1:]
            day = datetime.strptime(day_str, "%Y-%m-%d").date()
            start = datetime.strptime(start_str, "%H:%M").time()
            end = datetime.strptime(end_str, "%H:%M").time()
            busy[(who, day)] = [(minutes(start), minutes(end))]
        else:
            key = parts[0]
            settings[key] = parts[1:]
    days = settings["days"]
    first = date.fromisoformat(days[0])
    last = date.fromisoformat(days[1])
    hours = settings["hours"]
    open_at, close_at = (datetime.strptime(t, "%H:%M").time()) for t in hours
    need = int(settings["duration"][0])
    buffer = int(settings.get("buffer", 0))
    day = first
    while day <= last:
        key = day.isoformat()
        taken = sorted(busy.get((("A", day),), []) + busy.get((("B", day),), []))
        slots = []
        cursor = open_at
        for start, end in taken:
            if start - cursor >= need:
                slots.append(f"{clock(cursor)}-{clock(start)}")
            cursor = end
        if close_at - cursor >= need:
            slots.append(f"{clock(cursor)}-{clock(close_at)}")
        free_intervals = []
        current_start = open_at
        for interval in slots:
            slot_start, slot_end = map(clock, interval.split("-"))
            if current_start < slot_start:
                free_intervals.append((current_start, slot_start))
            current_start = slot_end
        if current_start < close_at:
            free_intervals.append((current_start, close_at))
        available_slots = []
        for start, end in free_intervals:
            duration = (end - start).total_seconds() / 60
            if duration >= need:
                available_slots.append(f"{start}-{end}")
        print(key, " ".join(available_slots) or "none")
        day += timedelta(days=1)


if __name__ == "__main__":
    main()
